package execution

const planSchema = `{"type":"object","additionalProperties":false,"required":["summary","root_cause","files","strategy","tests","risks","unknowns"],"properties":{"summary":{"type":"string"},"root_cause":{"type":"string"},"files":{"type":"array","items":{"type":"string"}},"strategy":{"type":"string"},"tests":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["program","arguments"],"properties":{"program":{"type":"string"},"arguments":{"type":"array","items":{"type":"string"}}}}},"risks":{"type":"array","items":{"type":"string"}},"unknowns":{"type":"array","items":{"type":"string"}}}}`
const implementationSchema = `{"type":"object","additionalProperties":false,"required":["status","summary"],"properties":{"status":{"type":"string","enum":["IMPLEMENTED","BLOCKED","ENVIRONMENT_BLOCKED"]},"summary":{"type":"string"}}}`

const environmentCommandsSchema = `{"type":"array","items":{"type":"object","additionalProperties":false,"required":["program","arguments"],"properties":{"program":{"type":"string"},"arguments":{"type":"array","items":{"type":"string"}}}}}`
const environmentSchema = `{"type":"object","additionalProperties":false,"required":["summary","base_image","files","image_commands","workspace_commands","hook_commands","completion_gates","checks","environment","requirements","blockers"],"properties":{"summary":{"type":"string"},"base_image":{"type":"string"},"files":{"type":"array","items":{"type":"string"}},"image_commands":` + environmentCommandsSchema + `,"workspace_commands":` + environmentCommandsSchema + `,"hook_commands":` + environmentCommandsSchema + `,"completion_gates":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["requirement","source","action","binding","checks"],"properties":{"requirement":{"type":"string"},"source":{"type":"string"},"action":{"type":"string"},"binding":{"type":"string","enum":["working_tree","commit"]},"checks":` + environmentCommandsSchema + `}}},"checks":` + environmentCommandsSchema + `,"environment":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["name","value"],"properties":{"name":{"type":"string"},"value":{"type":"string"}}}},"requirements":{"type":"array","items":{"type":"string"}},"blockers":{"type":"array","items":{"type":"string"}}}}`
const reviewSchema = `{"type":"object","additionalProperties":false,"required":["verdict","summary","findings"],"properties":{"verdict":{"type":"string","enum":["APPROVE","REQUEST_CHANGES"]},"summary":{"type":"string"},"findings":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["severity","file","line","explanation","recommended_fix"],"properties":{"severity":{"type":"string","enum":["critical","high","medium","low"]},"file":{"type":"string"},"line":{"type":"integer"},"explanation":{"type":"string"},"recommended_fix":{"type":"string"}}}}}}`
